// analyzer/namedTuples.ts:52
// Creates a new custom tuple factory class with named values.
// Supports both typed and untyped variants.
pub fn create_named_tuple_type(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    includes_types: bool,
    node_info: &AnalyzerNodeInfoAccessor,
) -> ClassType {
    // `strings.map((s) => s.d.value).join('')`.
    let join_string_values = |string_list: StringListNode| {
        let mut joined = JsString::from("");
        for s in string_list.d().strings.borrow().iter() {
            let value = match s.d() {
                ParseNodeDetails::String(d) => &d.value,
                ParseNodeDetails::FormatString(d) => &d.value,
                _ => unreachable!("a string list holds string nodes"),
            };
            joined = joined.concat(value);
        }
        joined
    };
    let has_name =
        |name: Option<NameNode>, value: &str| name.is_some_and(|name| name.d().value() == value);

    let file_info = node_info.get_file_info(error_node);
    let mut class_name = "namedtuple".to_string();
    let mut named_tuple_entries: JsSet<String> = JsSet::default();

    // The "rename" parameter is supported only in the untyped version.
    let mut allow_rename = false;
    if !includes_types {
        let rename_arg = arg_list.iter().find(|arg| {
            arg.arg_category() == ArgCategory::Simple && has_name(arg.name(), "rename")
        });

        if let Some(rename_value_expression) = rename_arg.and_then(|arg| arg.value_expression()) {
            let rename_value = evaluate_static_bool_expression(
                rename_value_expression,
                &file_info.execution_environment,
                &file_info.defined_constants,
                None,
                None,
            );
            if rename_value == Some(true) {
                allow_rename = true;
            }
        }
    }

    if arg_list.is_empty() {
        evaluator.add_diagnostic(
            DiagnosticRule::reportCallIssue,
            &LocMessage::named_tuple_first_arg(),
            error_node,
            None,
        );
    } else {
        let name_arg = &arg_list[0];
        if name_arg.arg_category() != ArgCategory::Simple {
            evaluator.add_diagnostic(
                DiagnosticRule::reportArgumentType,
                &LocMessage::named_tuple_first_arg(),
                arg_list[0].value_expression().unwrap_or(error_node),
                None,
            );
        } else if let Some(name_string_list) =
            name_arg.value_expression().and_then(StringListNode::cast)
        {
            class_name = join_string_values(name_string_list).to_string_lossy();
        }
    }

    // Is there is a default arg? If so, is it defined in a way that we
    // can determine its length statically?
    let defaults_arg = arg_list.iter().find(|arg| has_name(arg.name(), "defaults"));
    let mut default_arg_count: Option<i32> = Some(0);
    if let Some(defaults_value_expression) = defaults_arg.and_then(|arg| arg.value_expression()) {
        let defaults_arg_type = evaluator
            .get_type_of_expression(defaults_value_expression, EvalFlags::None, None)
            .type_
            .get();
        let static_tuple_length = if is_class_instance(defaults_arg_type)
            && is_tuple_class(ClassType(defaults_arg_type))
            && !is_unbounded_tuple_class(ClassType(defaults_arg_type)).unwrap_or(false)
        {
            ClassType(defaults_arg_type)
                .d()
                .priv_
                .borrow()
                .tuple_type_args
                .map(|tuple_type_args| tuple_type_args.get().borrow())
                .as_deref()
                .map(|tuple_type_args| tuple_type_args.len() as i32)
        } else {
            None
        };
        default_arg_count = static_tuple_length;
    }

    let named_tuple_type = evaluator
        .get_typing_type(error_node, "NamedTuple")
        .unwrap_or_else(|| UnknownType::create(false).0);

    let class_type = ClassType::create_instantiable(
        &class_name,
        &get_class_full_name(error_node, &file_info.module_name, &class_name),
        &file_info.module_name,
        &file_info.file_uri,
        ClassTypeFlags::ValidTypeAliasClass,
        get_type_source_id(error_node),
        /* declaredMetaclass */ None,
        if is_instantiable_class(named_tuple_type) {
            ClassType(named_tuple_type)
                .d()
                .shared
                .get()
                .effective_metaclass
                .get()
        } else {
            Some(UnknownType::create(false).0)
        },
        None,
    );
    Rc::make_mut(&mut *class_type
        .d()
        .shared
        .get()
        .base_classes
        .borrow_mut())
        .push(named_tuple_type);
    *class_type.d().shared.get().type_var_scope_id.borrow_mut() =
        Some(get_scope_id_for_node(error_node, node_info.reader()));

    let class_fields = ClassType::get_symbol_table(class_type);
    class_fields.set(
        "__class__",
        Symbol::create_with_type(
            SymbolFlags::ClassMember | SymbolFlags::IgnoredForProtocolMatch,
            class_type.0,
            None,
        ),
    );

    let class_type_var = synthesize_type_var_for_self_cls(class_type, /* isClsParam */ true);
    let constructor_type =
        FunctionType::create_synthesized_instance("__new__", FunctionTypeFlags::ConstructorMethod);
    constructor_type
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(convert_to_instance(class_type_var.0, true)));
    constructor_type
        .d()
        .priv_
        .borrow_mut()
        .constructor_type_var_scope_id = get_type_var_scope_id(class_type.0);
    if is_assignment_to_defaults_following_named_tuple(error_node) {
        let constructor_shared = constructor_type.d().shared.get();
        constructor_shared
            .flags
            .set(constructor_shared.flags.get() | FunctionTypeFlags::DisableDefaultChecks);
    }
    *constructor_type
        .d()
        .shared
        .get()
        .type_var_scope_id
        .borrow_mut() = *class_type
        .d()
        .shared
        .get()
        .type_var_scope_id
        .borrow();
    FunctionType::add_param(
        constructor_type,
        &FunctionParam::create(
            ParamCategory::Simple,
            class_type_var.0,
            FunctionParamFlags::TypeDeclared,
            Some("cls"),
            None,
            None,
        ),
    );

    let mut match_args_names: Vec<String> = Vec::new();

    let self_param = FunctionParam::create(
        ParamCategory::Simple,
        synthesize_type_var_for_self_cls(class_type, /* isClsParam */ false).0,
        FunctionParamFlags::TypeDeclared,
        Some("self"),
        None,
        None,
    );

    let mut add_generic_get_attribute = false;
    let mut entry_types: Vec<P<Type>> = Vec::new();

    if arg_list.len() < 2 {
        evaluator.add_diagnostic(
            DiagnosticRule::reportCallIssue,
            &LocMessage::named_tuple_second_arg(),
            error_node,
            None,
        );
        add_generic_get_attribute = true;
    } else {
        let entries_arg = &arg_list[1];
        let entries_arg_value_expression = entries_arg.value_expression();
        if entries_arg.arg_category() != ArgCategory::Simple {
            add_generic_get_attribute = true;
        } else {
            if !includes_types
                && let Some(entries_string_list) =
                    entries_arg_value_expression.and_then(StringListNode::cast)
            {
                let entry_name_node = entries_string_list.0;
                // JS `/[,\s]+/`. Splitting the decoded text splits at the same
                // places: a lone surrogate decodes to U+FFFD, which is not a
                // separator.
                static ENTRY_SEPARATOR_REG_EX: LazyLock<Regex> =
                    LazyLock::new(|| Regex::new(&format!("[,{WHITESPACE_IN_CLASS}]+")).unwrap());
                let joined = join_string_values(entries_string_list).to_string_lossy();
                let entries: Vec<&str> = ENTRY_SEPARATOR_REG_EX.split(&joined).collect();
                let first_param_with_default_index = match default_arg_count {
                    None => 0,
                    Some(default_arg_count) => 0.max(entries.len() as i32 - default_arg_count),
                };
                for (index, &entry_name) in entries.iter().enumerate() {
                    let index = index as i32;
                    let mut entry_name = entry_name.js_trim().to_string();
                    if !entry_name.is_empty() {
                        entry_name = rename_underscore(
                            evaluator,
                            &entry_name,
                            allow_rename,
                            entry_name_node,
                            index,
                        );
                        entry_name = rename_keyword(
                            evaluator,
                            &entry_name,
                            allow_rename,
                            entry_name_node,
                            index,
                        );

                        let entry_type = UnknownType::create(false).0;
                        let param_info = FunctionParam::create(
                            ParamCategory::Simple,
                            entry_type,
                            FunctionParamFlags::TypeDeclared,
                            Some(&entry_name),
                            if index >= first_param_with_default_index {
                                Some(entry_type)
                            } else {
                                None
                            },
                            None,
                        );

                        FunctionType::add_param(constructor_type, &param_info);
                        let new_symbol =
                            Symbol::create_with_type(SymbolFlags::InstanceMember, entry_type, None);
                        match_args_names.push(entry_name.clone());

                        // We need to associate the declaration with a parse node.
                        // In this case it's just part of a string literal value.
                        // The definition provider won't necessarily take the
                        // user to the exact spot in the string, but it's close enough.
                        let declaration = Declaration::create(
                            DeclarationType::Variable,
                            entry_name_node,
                            file_info.file_uri,
                            convert_offsets_to_range(
                                entry_name_node.start.get(),
                                TextRange::get_end(entry_name_node.get()),
                                file_info.lines,
                            ),
                            file_info.module_name.clone(),
                            false,
                            VariableDeclarationDetails {
                                is_runtime_type_expression: Cell::new(Some(true)),
                                ..Default::default()
                            },
                        );
                        new_symbol.add_declaration(declaration);
                        class_fields.set(&entry_name, new_symbol);
                        entry_types.push(entry_type);
                    }
                }
            } else if let Some(entry_list) =
                entries_arg_value_expression.filter(|value_expression| {
                    value_expression.node_type == ParseNodeType::List
                        || value_expression.node_type == ParseNodeType::Tuple
                })
            {
                let mut entry_map: JsMap<String, String> = JsMap::default();
                let entry_expressions = match ListNode::cast(entry_list) {
                    Some(list_node) => list_node.d().items.borrow().clone(),
                    None => TupleNode(entry_list).d().items.borrow().clone(),
                };

                let first_param_with_default_index = match default_arg_count {
                    None => 0,
                    Some(default_arg_count) => {
                        0.max(entry_expressions.len() as i32 - default_arg_count)
                    }
                };

                for (index, &entry) in entry_expressions.iter().enumerate() {
                    let index = index as i32;
                    let mut entry_type_node: Option<ExpressionNode> = None;
                    let mut entry_type: Option<P<Type>> = None;
                    let mut entry_name_node: Option<ExpressionNode> = None;
                    let mut entry_name = String::new();

                    if includes_types {
                        // Handle the variant that includes name/type tuples.
                        let tuple_items =
                            TupleNode::cast(entry).map(|tuple| tuple.d().items.borrow().clone());
                        if let Some(tuple_items) = tuple_items.filter(|items| items.len() == 2) {
                            entry_name_node = Some(tuple_items[0]);
                            entry_type_node = Some(tuple_items[1]);
                            entry_type = Some(convert_to_instance(
                                evaluator
                                    .get_type_of_expression_expecting_type(tuple_items[1], None)
                                    .type_
                                    .get(),
                                true,
                            ));
                        } else {
                            evaluator.add_diagnostic(
                                DiagnosticRule::reportArgumentType,
                                &LocMessage::named_tuple_name_type(),
                                entry,
                                None,
                            );
                        }
                    } else {
                        entry_name_node = Some(entry);
                        entry_type = Some(UnknownType::create(false).0);
                    }

                    if let Some(entry_name_node) = entry_name_node {
                        let name_type_result = evaluator.get_type_of_expression(
                            entry_name_node,
                            EvalFlags::None,
                            None,
                        );
                        let name_type = name_type_result.type_.get();
                        if is_class_instance(name_type)
                            && ClassType::is_built_in(
                                ClassType(name_type),
                                Some(&[jsrt::atom!("str")]),
                            )
                            && is_literal_type(ClassType(name_type))
                        {
                            let literal_value = ClassType(name_type)
                                .d()
                                .priv_
                                .borrow()
                                .literal_value
                                .clone();
                            entry_name = match literal_value {
                                Some(LiteralValue::String(value)) => value.to_string_lossy(),
                                _ => unreachable!("a str literal holds a string"),
                            };

                            if entry_name.is_empty() {
                                evaluator.add_diagnostic(
                                    DiagnosticRule::reportGeneralTypeIssues,
                                    &LocMessage::named_tuple_empty_name(),
                                    entry_name_node,
                                    None,
                                );
                            } else {
                                entry_name = rename_underscore(
                                    evaluator,
                                    &entry_name,
                                    allow_rename,
                                    entry_name_node,
                                    index,
                                );
                                entry_name = rename_keyword(
                                    evaluator,
                                    &entry_name,
                                    allow_rename,
                                    entry_name_node,
                                    index,
                                );
                            }
                        } else {
                            add_generic_get_attribute = true;
                        }
                    } else {
                        add_generic_get_attribute = true;
                    }

                    if entry_name.is_empty() {
                        entry_name = format!("_{index}");
                    }

                    if entry_map.contains_key(&entry_name) {
                        evaluator.add_diagnostic(
                            DiagnosticRule::reportGeneralTypeIssues,
                            &LocMessage::named_tuple_name_unique(),
                            entry_name_node.unwrap_or(entry),
                            None,
                        );
                    }

                    // Record names in a map to detect duplicates.
                    entry_map.insert(entry_name.clone(), entry_name.clone());

                    let entry_type = entry_type.unwrap_or_else(|| UnknownType::create(false).0);

                    let param_info = FunctionParam::create(
                        ParamCategory::Simple,
                        entry_type,
                        if includes_types {
                            FunctionParamFlags::TypeDeclared
                        } else {
                            FunctionParamFlags::None
                        },
                        Some(&entry_name),
                        if index >= first_param_with_default_index {
                            Some(entry_type)
                        } else {
                            None
                        },
                        None,
                    );

                    FunctionType::add_param(constructor_type, &param_info);
                    entry_types.push(entry_type);
                    match_args_names.push(entry_name.clone());

                    let new_symbol = Symbol::create_with_type(
                        SymbolFlags::InstanceMember | SymbolFlags::NamedTupleMember,
                        entry_type,
                        None,
                    );
                    if let Some(entry_name_node) = entry_name_node
                        && entry_name_node.node_type == ParseNodeType::StringList
                    {
                        let declaration = Declaration::create(
                            DeclarationType::Variable,
                            entry_name_node,
                            file_info.file_uri,
                            convert_offsets_to_range(
                                entry_name_node.start.get(),
                                TextRange::get_end(entry_name_node.get()),
                                file_info.lines,
                            ),
                            file_info.module_name.clone(),
                            false,
                            VariableDeclarationDetails {
                                type_annotation_node: Cell::new(entry_type_node),
                                ..Default::default()
                            },
                        );
                        new_symbol.add_declaration(declaration);
                    }
                    class_fields.set(&entry_name, new_symbol);
                    named_tuple_entries.insert(entry_name);
                }

                // Set the type in the type cache for the dict node so it
                // doesn't get evaluated again.
                evaluator.set_type_result_for_node(
                    entry_list,
                    P::new_eval(TypeResult::new(UnknownType::create(false).0)),
                    EvalFlags::None,
                );
            } else {
                // A dynamic expression was used, so we can't evaluate
                // the named tuple statically.
                add_generic_get_attribute = true;
            }

            if let Some(entries_value_expression) = entries_arg_value_expression
                && !add_generic_get_attribute
            {
                // Set the type of the value expression node to Any so we don't attempt to
                // re-evaluate it later, potentially generating "partially unknown" errors
                // in strict mode.
                evaluator.set_type_result_for_node(
                    entries_value_expression,
                    P::new_eval(TypeResult::new(AnyType::create(false).0)),
                    EvalFlags::None,
                );
            }
        }
    }

    *class_type.d().shared.get().named_tuple_entries.borrow_mut() = Some(named_tuple_entries);

    if add_generic_get_attribute {
        constructor_type
            .d()
            .shared
            .get()
            .parameters
            .set(P::new_eval(RefCell::new(Vec::new())));
        FunctionType::add_default_params(constructor_type, false);
        entry_types.push(AnyType::create(/* isEllipsis */ false).0);
        entry_types.push(AnyType::create(/* isEllipsis */ true).0);
    }

    // Always use generic parameters for __init__.
    let init_type = FunctionType::create_synthesized_instance("__init__", FunctionTypeFlags::None);
    FunctionType::add_param(init_type, &self_param);
    FunctionType::add_default_params(init_type, false);
    init_type
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(evaluator.get_none_type()));
    init_type
        .d()
        .priv_
        .borrow_mut()
        .constructor_type_var_scope_id = get_type_var_scope_id(class_type.0);

    class_fields.set(
        "__new__",
        Symbol::create_with_type(SymbolFlags::ClassMember, constructor_type.0, None),
    );
    class_fields.set(
        "__init__",
        Symbol::create_with_type(SymbolFlags::ClassMember, init_type.0, None),
    );

    let len_type = FunctionType::create_synthesized_instance("__len__", FunctionTypeFlags::None);
    len_type
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(evaluator.get_built_in_object(error_node, jsrt::atom!("int"), None)));
    FunctionType::add_param(len_type, &self_param);
    class_fields.set(
        "__len__",
        Symbol::create_with_type(SymbolFlags::ClassMember, len_type.0, None),
    );

    if add_generic_get_attribute {
        let get_attrib_type =
            FunctionType::create_synthesized_instance("__getattribute__", FunctionTypeFlags::None);
        get_attrib_type
            .d()
            .shared
            .get()
            .declared_return_type
            .set(Some(AnyType::create(false).0));
        FunctionType::add_param(get_attrib_type, &self_param);
        FunctionType::add_param(
            get_attrib_type,
            &FunctionParam::create(
                ParamCategory::Simple,
                evaluator.get_built_in_object(error_node, jsrt::atom!("str"), None),
                FunctionParamFlags::TypeDeclared,
                Some("name"),
                None,
                None,
            ),
        );
        class_fields.set(
            "__getattribute__",
            Symbol::create_with_type(SymbolFlags::ClassMember, get_attrib_type.0, None),
        );
    }

    let tuple_class_type = evaluator.get_built_in_type(error_node, jsrt::atom!("tuple"));

    // Synthesize the __match_args__ class variable.
    let str_type = evaluator.get_built_in_type(error_node, jsrt::atom!("str"));
    if !add_generic_get_attribute
        && is_instantiable_class(str_type)
        && is_instantiable_class(tuple_class_type)
    {
        let literal_types: Vec<TupleTypeArg> = match_args_names
            .iter()
            .map(|name| TupleTypeArg {
                type_: ClassType::clone_as_instance(
                    ClassType::clone_with_literal(
                        ClassType(str_type),
                        Some(LiteralValue::String(name.into())),
                    ),
                    true,
                )
                .0,
                is_unbounded: false,
                is_optional: None,
            })
            .collect();
        let match_args_type = ClassType::clone_as_instance(
            specialize_tuple_class(ClassType(tuple_class_type), &literal_types, true, false),
            true,
        );
        class_fields.set(
            "__match_args__",
            Symbol::create_with_type(SymbolFlags::ClassMember, match_args_type.0, None),
        );
    }

    update_named_tuple_base_class(class_type, &entry_types, !add_generic_get_attribute);

    compute_mro_linearization(class_type);

    class_type
}

// analyzer/namedTuples.ts:426
pub fn update_named_tuple_base_class(
    class_type: ClassType,
    type_args: &[P<Type>],
    is_type_arg_explicit: bool,
) -> bool {
    let mut is_update_needed = false;

    let class_shared = class_type.d().shared.get();
    let base_classes = class_shared.base_classes.borrow().clone();
    let new_base_classes: Vec<P<Type>> = base_classes
        .iter().copied()
        .map(|base_class| {
            if !is_instantiable_class(base_class)
                || !ClassType::is_built_in(ClassType(base_class), Some(&[jsrt::atom!("NamedTuple")]))
            {
                return base_class;
            }

            let mut tuple_type_args: Vec<TupleTypeArg> = Vec::new();

            if !is_type_arg_explicit {
                tuple_type_args.push(TupleTypeArg {
                    type_: if !type_args.is_empty() {
                        combine_types(type_args, None)
                    } else {
                        UnknownType::create(false).0
                    },
                    is_unbounded: true,
                    is_optional: None,
                });
            } else {
                for &t in type_args {
                    tuple_type_args.push(TupleTypeArg {
                        type_: t,
                        is_unbounded: false,
                        is_optional: None,
                    });
                }
            }

            // Create a copy of the NamedTuple class that replaces the tuple base class.
            let cloned_named_tuple_class = ClassType::specialize(
                ClassType(base_class),
                /* typeArgs */ None,
                Some(is_type_arg_explicit),
                false,
                None,
                None,
            );
            // `{ ...clonedNamedTupleClass.shared }`: a shallow copy. Handles (the
            // symbol table, `P` fields) stay shared; arrays, sets and maps are copied.
            let shared = cloned_named_tuple_class.d().shared.get();
            cloned_named_tuple_class
                .d()
                .shared
                .set(P::new_eval(ClassDetailsShared {
                    name: shared.name,
                    full_name: shared.full_name,
                    module_name: shared.module_name.clone(),
                    file_uri: shared.file_uri,
                    flags: Cell::new(shared.flags.get()),
                    type_source_id: shared.type_source_id,
                    base_classes: RefCell::new(shared.base_classes.borrow().clone()),
                    mro: RefCell::new(shared.mro.borrow().clone()),
                    declaration: Cell::new(shared.declaration.get()),
                    declared_metaclass: Cell::new(shared.declared_metaclass.get()),
                    effective_metaclass: Cell::new(shared.effective_metaclass.get()),
                    fields: Cell::new(shared.fields.get()),
                    type_params: RefCell::new(shared.type_params.borrow().clone()),
                    type_var_scope_id: RefCell::new(*shared.type_var_scope_id.borrow()),
                    doc_string: shared.doc_string.clone(),
                    data_class_entries: RefCell::new(shared.data_class_entries.borrow().clone()),
                    data_class_behaviors: Cell::new(shared.data_class_behaviors.get()),
                    named_tuple_entries: RefCell::new(shared.named_tuple_entries.borrow().clone()),
                    typed_dict_entries: Cell::new(shared.typed_dict_entries.get()),
                    typed_dict_extra_items_expr: Cell::new(
                        shared.typed_dict_extra_items_expr.get(),
                    ),
                    local_slots_names: RefCell::new(shared.local_slots_names.borrow().clone()),
                    has_non_empty_slots: Cell::new(shared.has_non_empty_slots.get()),
                    deprecated_message: RefCell::new(shared.deprecated_message.borrow().clone()),
                    protocol_compatibility: RefCell::new(
                        shared.protocol_compatibility.borrow().clone(),
                    ),
                    class_data_class_transform: Cell::new(shared.class_data_class_transform.get()),
                    requires_variance_inference: Cell::new(
                        shared.requires_variance_inference.get(),
                    ),
                    is_instance_hashable: Cell::new(shared.is_instance_hashable.get()),
                    synthesize_methods_deferred: RefCell::new(
                        shared.synthesize_methods_deferred.borrow().clone(),
                    ),
                    synthesize_data_class_slots_deferred: RefCell::new(
                        shared.synthesize_data_class_slots_deferred.borrow().clone(),
                    ),
                    calculate_inherited_slots_names_deferred: RefCell::new(
                        shared
                            .calculate_inherited_slots_names_deferred
                            .borrow()
                            .clone(),
                    ),
                    inherited_slots_names_cached: RefCell::new(
                        shared.inherited_slots_names_cached.borrow().clone(),
                    ),
                }));

            let cloned_shared = cloned_named_tuple_class.d().shared.get();
            let named_tuple_base_classes = cloned_shared.base_classes.borrow().clone();
            let new_named_tuple_base_classes: Vec<P<Type>> = named_tuple_base_classes
                .iter().copied()
                .map(|named_tuple_base_class| {
                    if !is_instantiable_class(named_tuple_base_class)
                        || !ClassType::is_built_in(
                            ClassType(named_tuple_base_class),
                            Some(&[jsrt::atom!("tuple")]),
                        )
                    {
                        return named_tuple_base_class;
                    }

                    specialize_tuple_class(
                        ClassType(named_tuple_base_class),
                        &tuple_type_args,
                        is_type_arg_explicit,
                        false,
                    )
                    .0
                })
                .collect();
            *cloned_shared.base_classes.borrow_mut() = Rc::new(new_named_tuple_base_classes);

            compute_mro_linearization(cloned_named_tuple_class);

            is_update_needed = true;
            cloned_named_tuple_class.0
        })
        .collect();
    *class_shared.base_classes.borrow_mut() = Rc::new(new_base_classes);

    is_update_needed
}

// analyzer/namedTuples.ts:470
pub(crate) fn rename_keyword(
    evaluator: &TypeEvaluator,
    name: &str,
    allow_rename: bool,
    error_node: ExpressionNode,
    index: i32,
) -> String {
    // Determine whether the name is a keyword in python.
    let is_keyword = Tokenizer::is_python_keyword(name, false);

    if !is_keyword {
        // No rename necessary.
        return name.to_string();
    }

    if allow_rename {
        // Rename based on index.
        return format!("_{index}");
    }

    evaluator.add_diagnostic(
        DiagnosticRule::reportGeneralTypeIssues,
        &LocMessage::named_tuple_name_keyword(),
        error_node,
        None,
    );
    name.to_string()
}

// analyzer/namedTuples.ts:494
pub(crate) fn rename_underscore(
    evaluator: &TypeEvaluator,
    name: &str,
    allow_rename: bool,
    error_node: ExpressionNode,
    index: i32,
) -> String {
    if !name.starts_with('_') {
        // No rename necessary.
        return name.to_string();
    }

    if allow_rename {
        // Rename based on index.
        return format!("_{index}");
    }

    evaluator.add_diagnostic(
        DiagnosticRule::reportGeneralTypeIssues,
        &LocMessage::named_tuple_field_underscore(),
        error_node,
        None,
    );

    name.to_string()
}
